pub const CurrentReorgMetaVersion: i64 = 1;
/// AnalyzeStateNone means the analyze process is not started yet.
pub const AnalyzeStateNone: isize = 0;
/// AnalyzeStateRunning means the analyze process is running.
pub const AnalyzeStateRunning: isize = 1;
/// AnalyzeStateSkipped means the analyze process is skipped.
pub const AnalyzeStateSkipped: isize = 2;
/// AnalyzeStateDone means the analyze process is done.
pub const AnalyzeStateDone: isize = 3;
/// AnalyzeStateTimeout means the analyze process is timed out.
pub const AnalyzeStateTimeout: isize = 4;
/// AnalyzeStateFailed means the analyze process is failed.
pub const AnalyzeStateFailed: isize = 5;
/// ReorgTypeNone means the backfill task is not started yet.
pub const ReorgTypeNone: ReorgType = ReorgType(0);
/// ReorgTypeTxn means the index records are backfill with transactions.
/// All the index KVs are written through the transaction interface.
/// This is the original backfill implementation.
pub const ReorgTypeTxn: ReorgType = ReorgType(1);
/// ReorgTypeIngest means the index records are backfill with lightning.
/// The index KVs are encoded to SST files and imported to the storage directly.
/// The incremental index KVs written by DML are redirected to a temporary index.
/// After the backfill is finished, the temporary index records are merged back to the original index.
pub const ReorgTypeIngest: ReorgType = ReorgType(2);
/// ReorgTypeTxnMerge means backfill with transactions and merge incremental changes.
/// The backfill index KVs are written through the transaction interface.
/// The incremental index KVs written by DML are redirected to a temporary index.
/// After the backfill is finished, the temporary index records are merged back to the original index.
pub const ReorgTypeTxnMerge: ReorgType = ReorgType(3);

// ---------------------------------------------------------------- bdr.go

/// Go `model.DDLBDRType` (a Go string type; `Cow` so that its constants are `const`).
#[derive(Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct DDLBDRType(pub Cow<'static, str>);
/// UnsafeDDL means the DDL can't be executed by user when cluster is Primary/Secondary.
pub const UnsafeDDL: DDLBDRType = DDLBDRType(Cow::Borrowed("unsafe DDL"));
/// SafeDDL means the DDL can be executed by user when cluster is Primary.
pub const SafeDDL: DDLBDRType = DDLBDRType(Cow::Borrowed("safe DDL"));
/// UnmanagementDDL means the DDL can't be synced by CDC.
pub const UnmanagementDDL: DDLBDRType = DDLBDRType(Cow::Borrowed("unmanagement DDL"));
/// UnknownDDL means the DDL is unknown.
pub const UnknownDDL: DDLBDRType = DDLBDRType(Cow::Borrowed("unknown DDL"));
